-- What kittiwake sends the frozen staking archive (/legacy-flows), a serve-only unit. One statement per line.
-- Both end at LEGACY_HISTORY_END_EXCLUSIVE (1787555748), where the live nest takes over.
-- kittiwake read/src/routes.rs delegation_flows(): daily_flow_sql(since, boundary, true) for Lodestar's default 90-day window
WITH events AS (SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18 AS tokens, 'inflow' AS direction FROM staking_legacy__stake_delegated UNION ALL SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18, 'outflow' FROM staking_legacy__stake_delegated_locked UNION ALL SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18, 'inflow' FROM staking__tokens_delegated UNION ALL SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18, 'outflow' FROM staking__tokens_undelegated) SELECT strftime(to_timestamp(block_timestamp), '%Y-%m-%d') AS date, SUM(CASE WHEN direction = 'inflow' THEN tokens ELSE 0 END) AS inflows, SUM(CASE WHEN direction = 'outflow' THEN tokens ELSE 0 END) AS outflows FROM events WHERE block_timestamp >= 1783296000 AND block_timestamp < 1787555748 GROUP BY 1 ORDER BY 1
-- kittiwake read/src/routes.rs delegation_flows(): the same for Lodestar's one-year window
WITH events AS (SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18 AS tokens, 'inflow' AS direction FROM staking_legacy__stake_delegated UNION ALL SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18, 'outflow' FROM staking_legacy__stake_delegated_locked UNION ALL SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18, 'inflow' FROM staking__tokens_delegated UNION ALL SELECT block_timestamp, CAST(tokens AS DOUBLE) / 1e18, 'outflow' FROM staking__tokens_undelegated) SELECT strftime(to_timestamp(block_timestamp), '%Y-%m-%d') AS date, SUM(CASE WHEN direction = 'inflow' THEN tokens ELSE 0 END) AS inflows, SUM(CASE WHEN direction = 'outflow' THEN tokens ELSE 0 END) AS outflows FROM events WHERE block_timestamp >= 1759536000 AND block_timestamp < 1787555748 GROUP BY 1 ORDER BY 1
